import React, { useState, useEffect } from 'react';
import { useHistory, useLocation } from 'react-router-dom';
import Header from '../../components/client/Header';
import Footer from '../../components/client/Footer';
import '../../styles/createComplaint.css';
import '../../styles/home.css';

function useQuery() {
    return new URLSearchParams(useLocation().search);
}

function CreateComplaint() {
    const history = useHistory();
    const query = useQuery();
    const orderId = query.get('orderId');
    const [topic, setTopic] = useState(orderId ? `Problème avec la commande n°${orderId}` : '');
    const [description, setDescription] = useState('');
    const userId = localStorage.getItem('userId');

    useEffect(() => {
        if (!userId) {
            history.push('/login');
        }
    }, [userId, history]);

    const handleSubmit = (e) => {
        e.preventDefault();
        fetch('http://localhost:3001/complaint', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ idUser: userId, topic, description })
        })
        .then(res => res.json())
        .then(data => {
            if (data.error) {
                alert(data.error);
            } else {
                alert('Réclamation créée avec succès.');
                history.push('/complaints');
            }
        })
        .catch(err => console.error('Erreur:', err));
    };

    const handleCancel = () => {
        history.goBack();
    };

    return (
        <div className="home">
            <Header />
            <div className="container create-complaint-container">
                <h1>Créer une réclamation</h1>
                <form className="complaint-form" onSubmit={handleSubmit}>
                    <div className="form-group">
                        <label>Sujet :</label>
                        <input 
                            type="text" 
                            value={topic} 
                            onChange={(e) => setTopic(e.target.value)} 
                            required 
                            className="complaint-input"
                        />
                    </div>
                    <div className="form-group">
                        <label>Description :</label>
                        <textarea 
                            value={description} 
                            onChange={(e) => setDescription(e.target.value)} 
                            required 
                            rows="6"
                            className="complaint-textarea"
                        />
                    </div>
                    <div className="complaint-buttons">
                        <button type="button" className="btn-cancel" onClick={handleCancel}>Annuler</button>
                        <button type="submit" className="btn-submit">Valider</button>
                    </div>
                </form>
            </div>
            <Footer />
        </div>
    );
}
export default CreateComplaint;
